    /**
     * Characters mode: include `a`–`z`.
     */
    public var lowercase: Bool
    /**
     * Characters mode: include `A`–`Z`.
     */
    public var uppercase: Bool
    /**
     * Characters mode: include `0`–`9`.
     */
    public var digits: Bool
    /**
     * Characters mode: include symbols.
     */
    public var symbols: Bool
    /**
     * Characters mode: leave out `0`, `O`, `1`, `l` and `I`.
     */
    public var avoidAmbiguous: Bool
    /**
     * Words mode: how many words (3–10, clamped).
     */
    public var words: UInt32
    /**
     * Words mode: what separates them.
     */
    public var separator: WordSeparator
    /**
     * Words mode: capitalize each word.
     */
    public var capitalize: Bool
    /**
     * Words mode: append one random digit.
     */
    public var includeDigit: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Which mode the sheet is in.
         */mode: GeneratorMode, 
        /**
         * Characters mode: how many characters (8–128, clamped).
         */length: UInt32, 
        /**
         * Characters mode: include `a`–`z`.
         */lowercase: Bool, 
        /**
         * Characters mode: include `A`–`Z`.
         */uppercase: Bool, 
        /**
         * Characters mode: include `0`–`9`.
         */digits: Bool, 
        /**
         * Characters mode: include symbols.
         */symbols: Bool, 
        /**
         * Characters mode: leave out `0`, `O`, `1`, `l` and `I`.
         */avoidAmbiguous: Bool, 
        /**
         * Words mode: how many words (3–10, clamped).
         */words: UInt32, 
        /**
         * Words mode: what separates them.
         */separator: WordSeparator, 
        /**
         * Words mode: capitalize each word.
         */capitalize: Bool, 
        /**
         * Words mode: append one random digit.
         */includeDigit: Bool) {
        self.mode = mode
        self.length = length
        self.lowercase = lowercase
        self.uppercase = uppercase
        self.digits = digits
        self.symbols = symbols
        self.avoidAmbiguous = avoidAmbiguous
        self.words = words
        self.separator = separator
        self.capitalize = capitalize
        self.includeDigit = includeDigit
    }

    

    
}

