        /**
         * Names of the logical vaults that had to be created.
         */vaultsCreated: [String], 
        /**
         * One line for the result pane.
         */headline: String, 
        /**
         * The preview, as it stood when the decision was made.
         */report: ImportReportView) {
        self.created = created
        self.updated = updated
        self.skipped = skipped
        self.keptBoth = keptBoth
        self.historyAdded = historyAdded
        self.vaultsCreated = vaultsCreated
        self.headline = headline
        self.report = report
    }

    

    
}

