        self.sourceName = sourceName
        self.headline = headline
        self.totals = totals
        self.byCategory = byCategory
        self.dropped = dropped
        self.decisions = decisions
        self.byAction = byAction
        self.duplicates = duplicates
        self.vaultAware = vaultAware
        self.items = items
    }

    

    
}

