        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .allowOnce
        
        case 2: return .allowSession(ttlSeconds: try FfiConverterUInt64.read(from: &buf), uses: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 3: return .deny
        
