/**
 * Everything that can go wrong on the way down into the core.
 *
 * Deliberately coarse. The app renders these to the user, and a lock screen that distinguishes
 * "wrong password" from "tampered file" would be telling an attacker something the core
 * deliberately does not (threat-model M-8) — so both arrive as [`FfiError::WrongCredential`].
 */
public 
enum FfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * There is no vault file at that path.
     */
    case NotFound(message: String)
    
    /**
     * There is already a vault file at that path.
     */
    case AlreadyExists(message: String)
    
    /**
     * The password, recovery code or platform key does not open this vault — or the file has
     * been tampered with. The two are not distinguished, on purpose.
     */
    case WrongCredential(message: String)
    
    /**
     * The vault has no slot of the kind that was asked for; typically, Touch ID was offered on a
     * vault that was never enrolled.
     */
    case NoSuchSlot(message: String)
    
    /**
     * No item, field, environment or logical vault with that identifier.
     */
    case NotPresent(message: String)
    
    /**
     * The argument was not of a shape the core accepts.
     */
    case Invalid(message: String)
    
    /**
     * Reading or writing the vault file failed.
     */
    case Io(message: String)
    

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension FfiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotFound(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .AlreadyExists(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .WrongCredential(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .NoSuchSlot(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .NotPresent(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .Invalid(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .Io(
            message: try FfiConverterString.read(from: &buf)
        )
        

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        case .NotFound(_ /* message is ignored*/):
            writeInt(&buf, Int32(1))
        case .AlreadyExists(_ /* message is ignored*/):
            writeInt(&buf, Int32(2))
        case .WrongCredential(_ /* message is ignored*/):
            writeInt(&buf, Int32(3))
        case .NoSuchSlot(_ /* message is ignored*/):
            writeInt(&buf, Int32(4))
        case .NotPresent(_ /* message is ignored*/):
            writeInt(&buf, Int32(5))
        case .Invalid(_ /* message is ignored*/):
            writeInt(&buf, Int32(6))
        case .Io(_ /* message is ignored*/):
            writeInt(&buf, Int32(7))

        
        }
    }
}


